<template><div><PageHeader title="Reports" description="Export operational reports for learners, courses, attendance and certification."></PageHeader><div class="report-grid"><div v-for="report in reports" :key="report.title" class="report-card"><div class="report-icon">{{report.icon}}</div><h3>{{report.title}}</h3><p>{{report.description}}</p><button class="btn secondary small" @click="run(report.title)">Generate report</button></div></div><div class="card" style="margin-top:18px"><div class="card-header"><h3>Report builder</h3><span class="section-note">Choose filters, preview, export</span></div><div class="form-section"><div class="form-grid-3"><div class="field"><label>Date range</label><select class="select"><option>This month</option><option>Last month</option><option>This quarter</option></select></div><div class="field"><label>Course</label><select class="select"><option>All courses</option><option>Laravel Fundamentals</option></select></div><div class="field"><label>Status</label><select class="select"><option>All statuses</option><option>Active</option><option>Completed</option></select></div></div></div><div class="card-pad"><div class="info-list"><div class="info-box"><span>Rows</span><strong>1,248</strong></div><div class="info-box"><span>Average attendance</span><strong>91.8%</strong></div><div class="info-box"><span>Certificates issued</span><strong>84</strong></div><div class="info-box"><span>Completion rate</span><strong>87.4%</strong></div></div></div><div class="form-actions"><button class="btn secondary">Export CSV</button><button class="btn primary">Export PDF</button></div></div></div></template>
<script setup lang="ts">import PageHeader from '../components/PageHeader.vue';import {useToast} from '../composables/useToast';const {push}=useToast();const reports=[{title:'Learner report',description:'Enrollment, profile and progress snapshot.',icon:'◌'},{title:'Attendance report',description:'Session attendance and exceptions.',icon:'✓'},{title:'Course performance',description:'Completion and assessment performance.',icon:'▦'},{title:'Trainer report',description:'Trainer sessions, cohorts and utilization.',icon:'♧'},{title:'Certificate report',description:'Issued, pending and revoked certificates.',icon:'▱'},{title:'Batch report',description:'Cohort status, schedule and capacity.',icon:'▤'}];function run(n:string){push(`${n} is being generated.`,'info')}</script>
